import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.BEUshCVJ.js";const p=JSON.parse('{"title":"错误码参考","description":"","frontmatter":{},"headers":[],"relativePath":"zh/troubleshooting/error-codes.md","filePath":"zh/troubleshooting/error-codes.md","lastUpdated":null}'),s={name:"zh/troubleshooting/error-codes.md"};function h(l,a,n,c,i,d){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="错误码参考" tabindex="-1">错误码参考 <a class="header-anchor" href="#错误码参考" aria-label="Permalink to &quot;错误码参考&quot;">​</a></h1><p>MeetCue 的每条提示都带有一个错误码，例如 <code>MC-AUD-001</code>。在下面找到对应的错误码，查看含义与解决办法。应用里的“查看解决办法”按钮会直接打开本页对应的位置。</p><h2 id="音频" tabindex="-1">音频 <a class="header-anchor" href="#音频" aria-label="Permalink to &quot;音频&quot;">​</a></h2><h3 id="mc-aud-001" tabindex="-1">MC-AUD-001 <a class="header-anchor" href="#mc-aud-001" aria-label="Permalink to &quot;MC-AUD-001 {#mc-aud-001}&quot;">​</a></h3><p><strong>音频设备被其他程序独占</strong> · 错误</p><p>解决办法: 在声音设置中打开该设备的属性，在“高级”选项卡里取消勾选“允许应用程序独占控制该设备”。</p><h3 id="mc-aud-002" tabindex="-1">MC-AUD-002 <a class="header-anchor" href="#mc-aud-002" aria-label="Permalink to &quot;MC-AUD-002 {#mc-aud-002}&quot;">​</a></h3><p><strong>麦克风被禁止访问或已静音</strong> · 错误</p><p>解决办法: 在系统隐私设置里允许 MeetCue 访问麦克风（macOS：隐私与安全性 › 麦克风），并确认麦克风没有被静音（静音键、耳机开关或声音设置），然后重新开始拾取。</p><h3 id="mc-aud-003" tabindex="-1">MC-AUD-003 <a class="header-anchor" href="#mc-aud-003" aria-label="Permalink to &quot;MC-AUD-003 {#mc-aud-003}&quot;">​</a></h3><p><strong>找不到可用的音频设备</strong> · 错误</p><p>解决办法: 连接麦克风或扬声器，确认它们在声音设置中已启用，然后在 设置 › 音频 中重新选择。</p><h3 id="mc-aud-004" tabindex="-1">MC-AUD-004 <a class="header-anchor" href="#mc-aud-004" aria-label="Permalink to &quot;MC-AUD-004 {#mc-aud-004}&quot;">​</a></h3><p><strong>音频设备已切换，采集已自动恢复</strong> · 提示</p><p>解决办法: 无需操作。若电平条不再跳动，请在 设置 › 音频 中重新选择设备。</p><h3 id="mc-aud-005" tabindex="-1">MC-AUD-005 <a class="header-anchor" href="#mc-aud-005" aria-label="Permalink to &quot;MC-AUD-005 {#mc-aud-005}&quot;">​</a></h3><p><strong>系统声音通道只收到静音</strong> · 警告</p><p>解决办法: 确认会议声音从默认播放设备输出。测试时将扬声器静音或戴上耳机，避免麦克风代替环回通道录到声音。</p><h3 id="mc-aud-006" tabindex="-1">MC-AUD-006 <a class="header-anchor" href="#mc-aud-006" aria-label="Permalink to &quot;MC-AUD-006 {#mc-aud-006}&quot;">​</a></h3><p><strong>缺少系统声音录制权限</strong> · 错误</p><p>解决办法: 在 macOS 的 系统设置 › 隐私与安全性 › 屏幕与系统音频录制（旧版系统为“屏幕录制”）中允许 MeetCue，授权后退出并重新打开 MeetCue。</p><h3 id="mc-aud-900" tabindex="-1">MC-AUD-900 <a class="header-anchor" href="#mc-aud-900" aria-label="Permalink to &quot;MC-AUD-900 {#mc-aud-900}&quot;">​</a></h3><p><strong>此平台暂不支持音频采集</strong> · 错误</p><p>解决办法: 音频采集需要 Windows 或 macOS 13 及以上版本。练习模式关闭“问题语音转文字”后仍可使用。</p><h2 id="语音识别" tabindex="-1">语音识别 <a class="header-anchor" href="#语音识别" aria-label="Permalink to &quot;语音识别&quot;">​</a></h2><h3 id="mc-asr-001" tabindex="-1">MC-ASR-001 <a class="header-anchor" href="#mc-asr-001" aria-label="Permalink to &quot;MC-ASR-001 {#mc-asr-001}&quot;">​</a></h3><p><strong>语音识别 API 密钥无效</strong> · 错误</p><p>解决办法: 从供应商控制台重新复制密钥，粘贴到 设置 › 供应商与费用 中，然后点“验证”。</p><h3 id="mc-asr-002" tabindex="-1">MC-ASR-002 <a class="header-anchor" href="#mc-asr-002" aria-label="Permalink to &quot;MC-ASR-002 {#mc-asr-002}&quot;">​</a></h3><p><strong>无法连接语音识别服务</strong> · 错误</p><p>解决办法: 检查网络或代理设置，然后运行延迟探测，选择一个可以连通的端点。</p><h3 id="mc-asr-003" tabindex="-1">MC-ASR-003 <a class="header-anchor" href="#mc-asr-003" aria-label="Permalink to &quot;MC-ASR-003 {#mc-asr-003}&quot;">​</a></h3><p><strong>语音识别服务限流</strong> · 警告</p><p>解决办法: 稍等一分钟再试。如果反复出现，请到供应商控制台检查配额与余额。</p><h3 id="mc-asr-004" tabindex="-1">MC-ASR-004 <a class="header-anchor" href="#mc-asr-004" aria-label="Permalink to &quot;MC-ASR-004 {#mc-asr-004}&quot;">​</a></h3><p><strong>语音识别服务返回了无法识别的响应</strong> · 错误</p><p>解决办法: 将 MeetCue 升级到最新版本。若问题仍在，请导出诊断信息并提交 Issue。</p><h3 id="mc-asr-005" tabindex="-1">MC-ASR-005 <a class="header-anchor" href="#mc-asr-005" aria-label="Permalink to &quot;MC-ASR-005 {#mc-asr-005}&quot;">​</a></h3><p><strong>尚未配置语音识别供应商</strong> · 错误</p><p>解决办法: 在 设置 › 供应商与费用 中选择供应商并填写密钥，或者用演示模式在没有密钥的情况下体验。</p><h2 id="大模型" tabindex="-1">大模型 <a class="header-anchor" href="#大模型" aria-label="Permalink to &quot;大模型&quot;">​</a></h2><h3 id="mc-llm-001" tabindex="-1">MC-LLM-001 <a class="header-anchor" href="#mc-llm-001" aria-label="Permalink to &quot;MC-LLM-001 {#mc-llm-001}&quot;">​</a></h3><p><strong>提示生成超时</strong> · 警告</p><p>解决办法: 运行延迟探测，换用更快的模型或端点。下一个问题会照常生成提示。</p><h3 id="mc-llm-002" tabindex="-1">MC-LLM-002 <a class="header-anchor" href="#mc-llm-002" aria-label="Permalink to &quot;MC-LLM-002 {#mc-llm-002}&quot;">​</a></h3><p><strong>大模型 API 密钥无效</strong> · 错误</p><p>解决办法: 从供应商控制台重新复制密钥，粘贴到 设置 › 供应商与费用 中，然后点“验证”。</p><h3 id="mc-llm-003" tabindex="-1">MC-LLM-003 <a class="header-anchor" href="#mc-llm-003" aria-label="Permalink to &quot;MC-LLM-003 {#mc-llm-003}&quot;">​</a></h3><p><strong>大模型服务限流</strong> · 警告</p><p>解决办法: MeetCue 会自动重试。如果反复出现，请检查账户的速率限制与余额。</p><h3 id="mc-llm-004" tabindex="-1">MC-LLM-004 <a class="header-anchor" href="#mc-llm-004" aria-label="Permalink to &quot;MC-LLM-004 {#mc-llm-004}&quot;">​</a></h3><p><strong>所选模型不可用</strong> · 错误</p><p>解决办法: 在 设置 › 供应商与费用 中换一个模型。</p><h3 id="mc-llm-005" tabindex="-1">MC-LLM-005 <a class="header-anchor" href="#mc-llm-005" aria-label="Permalink to &quot;MC-LLM-005 {#mc-llm-005}&quot;">​</a></h3><p><strong>大模型请求失败</strong> · 错误</p><p>解决办法: 检查网络与供应商的服务状态页，然后重试。</p><h3 id="mc-llm-006" tabindex="-1">MC-LLM-006 <a class="header-anchor" href="#mc-llm-006" aria-label="Permalink to &quot;MC-LLM-006 {#mc-llm-006}&quot;">​</a></h3><p><strong>无法解析模型的输出</strong> · 警告</p><p>解决办法: 通常只是偶发。若经常出现，请为要点生成选择能力更强的模型。</p><h2 id="快捷键" tabindex="-1">快捷键 <a class="header-anchor" href="#快捷键" aria-label="Permalink to &quot;快捷键&quot;">​</a></h2><h3 id="mc-hk-001" tabindex="-1">MC-HK-001 <a class="header-anchor" href="#mc-hk-001" aria-label="Permalink to &quot;MC-HK-001 {#mc-hk-001}&quot;">​</a></h3><p><strong>快捷键已被其他程序占用</strong> · 警告</p><p>解决办法: 打开 设置 › 快捷键，为标红的项目换一个组合键。</p><h2 id="系统" tabindex="-1">系统 <a class="header-anchor" href="#系统" aria-label="Permalink to &quot;系统&quot;">​</a></h2><h3 id="mc-sys-001" tabindex="-1">MC-SYS-001 <a class="header-anchor" href="#mc-sys-001" aria-label="Permalink to &quot;MC-SYS-001 {#mc-sys-001}&quot;">​</a></h3><p><strong>缺少 WebView2 运行时</strong> · 错误</p><p>解决办法: 从微软官网安装 Evergreen 版 WebView2 运行时，然后重新启动 MeetCue。</p><h3 id="mc-sys-002" tabindex="-1">MC-SYS-002 <a class="header-anchor" href="#mc-sys-002" aria-label="Permalink to &quot;MC-SYS-002 {#mc-sys-002}&quot;">​</a></h3><p><strong>设置改存在用户目录中</strong> · 提示</p><p>解决办法: MeetCue 无法写入程序旁边的 config 文件夹，因此改把设置保存在 %APPDATA%\\MeetCue。一切功能正常，此提示只显示一次。如希望设置保存在程序旁边（Scoop 的 persist 文件夹），请让该文件夹可写并重启 MeetCue。</p><h3 id="mc-sys-003" tabindex="-1">MC-SYS-003 <a class="header-anchor" href="#mc-sys-003" aria-label="Permalink to &quot;MC-SYS-003 {#mc-sys-003}&quot;">​</a></h3><p><strong>系统凭据库不可用</strong> · 错误</p><p>解决办法: API 密钥只保存在系统凭据库中。请确认凭据服务（凭据管理器、钥匙串或 Secret Service）正常运行后重试。</p><h3 id="mc-sys-004" tabindex="-1">MC-SYS-004 <a class="header-anchor" href="#mc-sys-004" aria-label="Permalink to &quot;MC-SYS-004 {#mc-sys-004}&quot;">​</a></h3><p><strong>此平台暂不支持该功能</strong> · 提示</p><p>解决办法: 该功能将在后续版本中支持，请查看文档中的平台支持表。</p><h3 id="mc-sys-005" tabindex="-1">MC-SYS-005 <a class="header-anchor" href="#mc-sys-005" aria-label="Permalink to &quot;MC-SYS-005 {#mc-sys-005}&quot;">​</a></h3><p><strong>设置未能保存</strong> · 错误</p><p>解决办法: 可能有其他程序（常见的是杀毒软件或同步工具）正在占用 settings.json。请再改一次；如果一直失败，请打开 设置 › 诊断，查看其中显示的设置文件夹，并确认它可以写入。</p><h3 id="mc-sys-006" tabindex="-1">MC-SYS-006 <a class="header-anchor" href="#mc-sys-006" aria-label="Permalink to &quot;MC-SYS-006 {#mc-sys-006}&quot;">​</a></h3><p><strong>MeetCue 未能完成该操作</strong> · 错误</p><p>解决办法: 请重试。如果反复出现，请在 设置 › 诊断 中导出诊断信息并提交 Issue，日志中会写明失败的操作。</p><h2 id="网络" tabindex="-1">网络 <a class="header-anchor" href="#网络" aria-label="Permalink to &quot;网络&quot;">​</a></h2><h3 id="mc-net-001" tabindex="-1">MC-NET-001 <a class="header-anchor" href="#mc-net-001" aria-label="Permalink to &quot;MC-NET-001 {#mc-net-001}&quot;">​</a></h3><p><strong>无法建立安全连接</strong> · 错误</p><p>解决办法: 如果所在网络使用 HTTPS 代理，请在 设置 › 供应商与费用 › 高级 中填写代理地址，并确认系统信任其证书。</p><h2 id="预算" tabindex="-1">预算 <a class="header-anchor" href="#预算" aria-label="Permalink to &quot;预算&quot;">​</a></h2><h3 id="mc-bud-001" tabindex="-1">MC-BUD-001 <a class="header-anchor" href="#mc-bud-001" aria-label="Permalink to &quot;MC-BUD-001 {#mc-bud-001}&quot;">​</a></h3><p><strong>预算已用 80%</strong> · 警告</p><p>解决办法: 花费已接近你设定的上限，如有需要可在 设置 › 供应商与费用 中调整预算。</p><h3 id="mc-bud-002" tabindex="-1">MC-BUD-002 <a class="header-anchor" href="#mc-bud-002" aria-label="Permalink to &quot;MC-BUD-002 {#mc-bud-002}&quot;">​</a></h3><p><strong>预算已用完</strong> · 警告</p><p>解决办法: MeetCue 已按你的设置处理。如需继续，请在 设置 › 供应商与费用 中提高预算。</p><h2 id="练习" tabindex="-1">练习 <a class="header-anchor" href="#练习" aria-label="Permalink to &quot;练习&quot;">​</a></h2><h3 id="mc-prc-001" tabindex="-1">MC-PRC-001 <a class="header-anchor" href="#mc-prc-001" aria-label="Permalink to &quot;MC-PRC-001 {#mc-prc-001}&quot;">​</a></h3><p><strong>无法读取练习文件</strong> · 错误</p><p>解决办法: 请使用 .srt、.vtt、.txt、.md 或 .csv 文件，格式示例见“文件格式”参考页。</p><h3 id="mc-prc-002" tabindex="-1">MC-PRC-002 <a class="header-anchor" href="#mc-prc-002" aria-label="Permalink to &quot;MC-PRC-002 {#mc-prc-002}&quot;">​</a></h3><p><strong>语音合成不可用</strong> · 警告</p><p>解决办法: 在系统设置中安装对应语言的语音，或改为只在屏幕上显示问题进行练习。</p><h2 id="诊断" tabindex="-1">诊断 <a class="header-anchor" href="#诊断" aria-label="Permalink to &quot;诊断&quot;">​</a></h2><h3 id="mc-diag-001" tabindex="-1">MC-DIAG-001 <a class="header-anchor" href="#mc-diag-001" aria-label="Permalink to &quot;MC-DIAG-001 {#mc-diag-001}&quot;">​</a></h3><p><strong>诊断信息导出失败</strong> · 错误</p><p>解决办法: 换一个有写入权限的文件夹（例如“文档”）后重试。</p><h2 id="知识库" tabindex="-1">知识库 <a class="header-anchor" href="#知识库" aria-label="Permalink to &quot;知识库&quot;">​</a></h2><h3 id="mc-kb-001" tabindex="-1">MC-KB-001 <a class="header-anchor" href="#mc-kb-001" aria-label="Permalink to &quot;MC-KB-001 {#mc-kb-001}&quot;">​</a></h3><p><strong>无法读取知识库文件</strong> · 错误</p><p>解决办法: 请使用 PDF、Word（.docx）、Excel（.xlsx）、PowerPoint（.pptx）、OpenDocument、RTF、HTML、文本或 Markdown 文件。旧版 .doc、.xls、.ppt 请先另存为新格式，扫描版 PDF 请先做文字识别再导出。</p><hr><p>仍未解决？请<a href="./diagnostics">导出诊断信息</a>，并带上错误码提交 Issue。</p>',110)])])}const u=e(s,[["render",h]]);export{p as __pageData,u as default};
